<template><section class="page"><div class="toolbar"><button class="primary" @click="showCreate = true">创建租户</button><button @click="load">刷新</button></div><StateWrapper :loading="loading" :error="error" :empty="!tenants.length" empty-text="暂无租户。" @retry="load"><table><thead><tr><th>编码</th><th>名称</th><th>成员</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="tenant in tenants" :key="tenant.id"><td>{{ tenant.code }}</td><td>{{ tenant.name }}</td><td>{{ tenant.user_count }}</td><td>{{ tenant.is_active ? '启用' : '停用' }}</td><td><button @click="toggle(tenant)">{{ tenant.is_active ? '停用' : '启用' }}</button><button @click="openQuota(tenant)">配额</button></td></tr></tbody></table></StateWrapper><form v-if="showCreate" class="modal" @submit.prevent="create"><h3>创建租户和首个管理员</h3><input v-model.trim="form.code" placeholder="租户编码" /><input v-model.trim="form.name" placeholder="租户名称" /><input v-model.trim="form.admin_username" placeholder="管理员用户名" /><input v-model="form.admin_password" type="password" placeholder="管理员密码（至少 8 位）" /><button class="primary">创建</button><button type="button" @click="showCreate=false">取消</button></form><form v-if="quotaTenant" class="modal" @submit.prevent="saveQuota"><h3>{{ quotaTenant.name }}：配额设置</h3><input v-model.number="quota.tokens" type="number" min="0" placeholder="每月 Token 上限，留空不限" /><input v-model.number="quota.requests" type="number" min="0" placeholder="每月请求上限，留空不限" /><select v-model="quota.overage_policy"><option value="reject">超额拒绝</option><option value="soft_warn">超额放行并告警</option></select><button class="primary">保存</button><button type="button" @click="quotaTenant=null">取消</button></form></section></template>
<script setup>
import { onMounted, ref } from 'vue'; import { request } from '../api'; import StateWrapper from '../components/StateWrapper.vue'
const tenants=ref([]),loading=ref(false),error=ref(''),showCreate=ref(false),quotaTenant=ref(null),quota=ref({tokens:null,requests:null,overage_policy:'reject'}),form=ref({code:'',name:'',admin_username:'',admin_password:''})
async function load(){loading.value=true;error.value='';try{tenants.value=await request('/api/admin/tenants')}catch(e){error.value=e.message}finally{loading.value=false}}
async function create(){try{await request('/api/admin/tenants',{method:'POST',body:JSON.stringify(form.value)});showCreate.value=false;form.value={code:'',name:'',admin_username:'',admin_password:''};await load()}catch(e){error.value=e.message}}
async function toggle(tenant){try{await request(`/api/admin/tenants/${tenant.id}/${tenant.is_active?'disable':'enable'}`,{method:'POST'});await load()}catch(e){error.value=e.message}}
function openQuota(tenant){quotaTenant.value=tenant;quota.value={tokens:null,requests:null,overage_policy:'reject'}}
async function saveQuota(){try{await request(`/api/admin/tenants/${quotaTenant.value.id}/quota`,{method:'PATCH',body:JSON.stringify({quota_monthly_tokens:quota.value.tokens,quota_monthly_requests:quota.value.requests,overage_policy:quota.value.overage_policy})});quotaTenant.value=null;await load()}catch(e){error.value=e.message}}
onMounted(load)
</script>
